                        if ((((hex_digit_count2 > 0) and (hex_digit_count2 <= 6)) and (text.len == 0))) {
                            return .{ .result = UnicodeRange{ .start = first_hex_value, .end = second_hex_value } };
                        }
                    }
                }
            }
            return .{ .err = undefined };
    }

pub fn consumeQuestionMarks(text_in: []const u8) QmResult {
            var text = text_in;
            _ = &text;
            var question_marks: usize = 0;
            _ = &question_marks;
            while (bun.strings.splitFirstWithExpected(text, 63)) |rest| {
                question_marks = (question_marks + 1);
                text = rest;
            }
            return .{ .count = question_marks, .rest = text };
    }

pub fn consumeHex(text_in: []const u8) HexResult {
            var text = text_in;
            _ = &text;
            var value: u32 = 0;
            _ = &value;
            var digits: usize = 0;
            _ = &digits;
            while (bun.strings.splitFirst(text)) |result| {
                if (toHexDigit(result.first)) |digit_value| {
                    _ = &digit_value;
                    value = ((value * 16) + digit_value);
                    digits = (digits + 1);
                    text = result.rest;
                } else {
                    break;
                }
            }
            return .{ .value = value, .digits = digits, .rest = text };
    }

pub fn toHexDigit(b: u8) ?u32 {
            var digit = ((if (comptime @typeInfo(@TypeOf(b)) == .@"enum") cp_cast_int(u32, @intFromEnum(b)) else cp_cast_int(u32, b)) -% (if (comptime @typeInfo(@TypeOf(48)) == .@"enum") cp_cast_int(u32, @intFromEnum(48)) else cp_cast_int(u32, 48)));
            _ = &digit;
            if ((digit < 10)) {
                return digit;
            }
            digit = ((((if (comptime @typeInfo(@TypeOf(b)) == .@"enum") cp_cast_int(u32, @intFromEnum(b)) else cp_cast_int(u32, b)) | 32) -% (if (comptime @typeInfo(@TypeOf(97)) == .@"enum") cp_cast_int(u32, @intFromEnum(97)) else cp_cast_int(u32, 97))) +| 10);
            return (if ((digit < 16)) digit else null);
    }
    const QmResult = UnicodeRangeQmResult;
    const HexResult = UnicodeRangeHexResult;
};

pub const FontStyle = union(enum) {
    normal: void,
    italic: void,
    oblique: Size2D(css.css_values.angle.Angle),

pub fn parse(input: *css.Parser) Result(FontStyle) {
            const property = (switch (FontStyleProperty.parse(input)) {
.result => |vv| vv,
.err => |e| {
return .{ .err = e };
},
});
            return .{ .result = (switch (property) {
.normal => .normal,
.italic => .italic,
.oblique => |angle| {
{
                var second_angle = angle;
                _ = &second_angle;
                if (input.tryParse(css.css_values.angle.Angle.parse, .{}).asValue()) |a| {
                    _ = &a;
                    second_angle = a;
                }
                return .{ .result = .{ .oblique = .{ .a = angle, .b = second_angle } } };
            }
},
}) };
    }

pub fn toCss(self: FontStyle, dest: *Printer) PrintErr!void {
            switch (self) {
.normal => {
_ = try dest.writeStr("normal");
},
.italic => {
_ = try dest.writeStr("italic");
},
.oblique => |angle| {
_ = try dest.writeStr("oblique");
            if ((!angle.eql((&FontStyle.defaultObliqueAngle())))) {
                _ = try dest.writeChar(32);
                _ = try angle.toCss(dest);
            }
},
}
    }

pub fn defaultObliqueAngle() Size2D(Angle) {
            return .{ .a = FontStyleProperty.defaultObliqueAngle(), .b = FontStyleProperty.defaultObliqueAngle() };
    }
};

pub const FontFormat = union(enum) {
    woff: void,
    woff2: void,
    truetype: void,
    opentype: void,
    embedded_opentype: void,
    collection: void,
    svg: void,
    string: []const u8,

pub fn parse(input: *css.Parser) Result(FontFormat) {
            const s = (switch (input.expectIdentOrString()) {
.result => |vv| vv,
.err => |e| {
return .{ .err = e };
},
});
            if (bun.strings.eqlCaseInsensitiveASCIIICheckLength("woff", s)) {
                return .{ .result = .woff };
            } else {
                if (bun.strings.eqlCaseInsensitiveASCIIICheckLength("woff2", s)) {
                    return .{ .result = .woff2 };
                } else {
                    if (bun.strings.eqlCaseInsensitiveASCIIICheckLength("truetype", s)) {
                        return .{ .result = .truetype };
                    } else {
                        if (bun.strings.eqlCaseInsensitiveASCIIICheckLength("opentype", s)) {
                            return .{ .result = .opentype };
                        } else {
                            if (bun.strings.eqlCaseInsensitiveASCIIICheckLength("embedded-opentype", s)) {
                                return .{ .result = .embedded_opentype };
                            } else {
                                if (bun.strings.eqlCaseInsensitiveASCIIICheckLength("collection", s)) {
                                    return .{ .result = .collection };
                                } else {
                                    if (bun.strings.eqlCaseInsensitiveASCIIICheckLength("svg", s)) {
                                        return .{ .result = .svg };
                                    } else {
                                        return .{ .result = .{ .string = s } };
                                    }
                                }
                            }
                        }
                    }
                }
            }
    }

pub fn toCss(self: FontFormat, dest: *Printer) PrintErr!void {
            switch (self) {
.woff => {
_ = try dest.writeStr("woff");
},
.woff2 => {
_ = try dest.writeStr("woff2");
},
.truetype => {
_ = try dest.writeStr("truetype");
},
.opentype => {
_ = try dest.writeStr("opentype");
},
.embedded_opentype => {
_ = try dest.writeStr("embedded-opentype");
},
.collection => {
_ = try dest.writeStr("collection");
},
.svg => {
_ = try dest.writeStr("svg");
},
.string => {
_ = try dest.writeStr(self.string);
},
}
    }

pub fn deepClone(s: *const @This(), allocator: std.mem.Allocator) @This() {
            return css.implementDeepClone(@This(), s, allocator);
    }
};

pub const Source = union(enum) {
    url: UrlSource,
    local: fontprops.FontFamily,

pub fn parse(input: *css.Parser) Result(Source) {
            switch (input.tryParse(UrlSource.parse, .{})) {
.result => |url| {
return .{ .result = .{ .url = url } };
},
.err => |e| {
if (((e.kind == .basic) and (e.kind.basic == .at_rule_body_invalid))) {
                return .{ .err = e };
            }
},
}
            if (input.expectFunctionMatching("local").asErr()) |e| {
                _ = &e;
                return .{ .err = e };
            }
            const local = (switch (input.parseNestedBlock(fontprops.FontFamily, @as(void, undefined), SourceLocalFn.parseNestedBlock)) {
.result => |vv| vv,
.err => |e| {
return .{ .err = e };
},
});
            return .{ .result = .{ .local = local } };
    }

pub fn toCss(self: Source, dest: *Printer) PrintErr!void {
            switch (self) {
.url => {
_ = try self.url.toCss(dest);
},
.local => {
_ = try dest.writeStr("local(");
            _ = try self.local.toCss(dest);
            _ = try dest.writeChar(41);
},
}
    }

pub fn deepClone(s: *const @This(), allocator: std.mem.Allocator) @This() {
            return css.implementDeepClone(@This(), s, allocator);
    }
};

pub const UrlSource = struct {
    url: Url,
    format: ?FontFormat,
    tech: ArrayList(FontTechnology),

pub fn parse(input: *css.Parser) Result(UrlSource) {
            const url = (switch (Url.parse(input)) {
.result => |vv| vv,
.err => |e| {
return .{ .err = e };
},
});
            var format: ?FontFormat = null;
            _ = &format;
            if (input.tryParse(css.Parser.expectFunctionMatching, .{ "format" }).isOk()) {
                switch (input.parseNestedBlock(FontFormat, @as(void, undefined), css.voidWrap(FontFormat, FontFormat.parse))) {
.result => |vv| {
format = vv;
},
.err => |e| {
return .{ .err = e };
},
}
            }
            var tech: ArrayList(FontTechnology) = .{};
            _ = &tech;
            if (input.tryParse(css.Parser.expectFunctionMatching, .{ "tech" }).isOk()) {
                switch (input.parseNestedBlock(ArrayList(FontTechnology), @as(void, undefined), UrlSourceTechFn.parseNestedBlockFn)) {
.result => |vv| {
tech = vv;
},
.err => |e| {
return .{ .err = e };
},
}
            }
            return .{ .result = UrlSource{ .url = url, .format = format, .tech = tech } };
    }

pub fn toCss(self: UrlSource, dest: *Printer) PrintErr!void {
            _ = try self.url.toCss(dest);
            if (self.format) |format| {
                _ = &format;
                _ = try dest.whitespace();
                _ = try dest.writeStr("format(");
                _ = try format.toCss(dest);
                _ = try dest.writeChar(41);
            }
            if ((self.tech.items.len != 0)) {
                _ = try dest.whitespace();
                _ = try dest.writeStr("tech(");
                _ = try css.to_css.fromList(FontTechnology, self.tech.items, dest);
                _ = try dest.writeChar(41);
            }
    }

pub fn deepClone(self: UrlSource, allocator: std.mem.Allocator) @This() {
            const s = self;
            return css.implementDeepClone(@This(), (blk: {
            break :blk (&s);

}), allocator);
    }
};

pub const FontFaceRule = struct {
    properties: ArrayList(FontFaceProperty),
    loc: Location,

pub fn toCss(self: FontFaceRule, dest: *Printer) PrintErr!void {
            _ = try dest.writeStr("@font-face");
            _ = try dest.whitespace();
            _ = try dest.writeChar(123);
            _ = dest.indent();
            const len = self.properties.items.len;
            var i: usize = 0;
            _ = &i;
            for (self.properties.items) |prop| {
                _ = &prop;
                _ = try dest.newline();
                _ = try prop.toCss(dest);
                if (((i != (len - 1)) or (!dest.minify))) {
                    _ = try dest.writeChar(59);
                }
                i = (i + 1);
            }
            _ = dest.dedent();
            _ = try dest.newline();
            _ = try dest.writeChar(125);
    }

pub fn deepClone(self: FontFaceRule, allocator: std.mem.Allocator) This {
            const s = self;
            return css.implementDeepClone(@This(), (blk: {
            break :blk (&s);

}), allocator);
    }
    const This = @This();
};

