pub const FontFaceValueParser = struct {

pub fn parseValue(_: *FontFaceDeclarationParser, name: []const u8, input: *css.Parser) Result(Declaration) {
            const state = input.state();
            if (bun.strings.eqlCaseInsensitiveASCIIICheckLength(name, "src")) {
                if (input.parseCommaSeparated(Source, Source.parse).asValue()) |sources| {
                    _ = &sources;
                    return .{ .result = .{ .source = sources } };
                }
            } else {
                if (bun.strings.eqlCaseInsensitiveASCIIICheckLength(name, "font-family")) {
                    if (FontFamily.parse(input).asValue()) |c| {
                        _ = &c;
                        if (input.expectExhausted().isOk()) {
                            return .{ .result = .{ .font_family = c } };
                        }
                    }
                } else {
                    if (bun.strings.eqlCaseInsensitiveASCIIICheckLength(name, "font-weight")) {
                        if (Size2D(FontWeight).parse(input).asValue()) |c| {
                            _ = &c;
                            if (input.expectExhausted().isOk()) {
                                return .{ .result = .{ .font_weight = c } };
                            }
                        }
                    } else {
                        if (bun.strings.eqlCaseInsensitiveASCIIICheckLength(name, "font-style")) {
                            if (FontStyle.parse(input).asValue()) |c| {
                                _ = &c;
                                if (input.expectExhausted().isOk()) {
                                    return .{ .result = .{ .font_style = c } };
                                }
                            }
                        } else {
                            if (bun.strings.eqlCaseInsensitiveASCIIICheckLength(name, "font-stretch")) {
                                if (Size2D(FontStretch).parse(input).asValue()) |c| {
                                    _ = &c;
                                    if (input.expectExhausted().isOk()) {
                                        return .{ .result = .{ .font_stretch = c } };
                                    }
                                }
                            } else {
                                if (bun.strings.eqlCaseInsensitiveASCIIICheckLength(name, "unicode-range")) {
                                    if (input.parseList(UnicodeRange, UnicodeRange.parse).asValue()) |c| {
                                        _ = &c;
                                        if (input.expectExhausted().isOk()) {
                                            return .{ .result = .{ .unicode_range = c } };
                                        }
                                    }
                                } else {
                                }
                            }
                        }
                    }
                }
            }
            _ = input.reset((&state));
            const opts = css.ParserOptions.default(input.allocator(), null);
            return .{ .result = .{ .custom = (switch (CustomProperty.parse(CustomPropertyName.fromStr(name), input, (&opts))) {
.result => |v| v,
.err => |e| {
return .{ .err = e };
},
}) } };
    }
    pub const Declaration = FontFaceProperty;
};

